    // Função aprofundada para verificar se um campo está inativo/desabilitado na interface
    function isFieldDisabled(element) {
        if (!element) return true;

        // 1. Atributo disabled ou readonly nativo
        if (element.hasAttribute('disabled') || element.hasAttribute('readonly')) return true;
        if (element.disabled || element.readOnly) return true;

        // 2. Atributos ARIA
        if (element.getAttribute('aria-disabled') === 'true' || element.getAttribute('aria-readonly') === 'true') return true;

        // 3. Classes de desativação comuns (Material-UI)
        const className = element.className || '';
        if (typeof className === 'string') {
            if (className.includes('Mui-disabled') || className.includes('disabled') || className.includes('readonly')) return true;
        }

        // 4. Verificar elementos pais (containers desabilitados)
        let parent = element.parentElement;
        while (parent && parent.tagName !== 'FORM' && parent.tagName !== 'BODY') {
            if (parent.hasAttribute('disabled') || parent.getAttribute('aria-disabled') === 'true') return true;
            const parentClassName = parent.className || '';
            if (typeof parentClassName === 'string' && parentClassName.includes('Mui-disabled')) return true;
            parent = parent.parentElement;
        }

        return false;
    }

    // Função avançada para setar valor e disparar todos os ciclos de eventos (React, Masks, Paste, KeyEvents)
    
    async function typeDigitByDigit(input, text) {
        if (!input) return;
        input.focus();
        
        // Garante que separador decimal seja sempre vírgula (ex: 53.5579 -> 53,5579)
        let str = String(text).trim();
        if (str.includes('.') && !str.includes(',')) {
            str = str.replace('.', ',');
        }
        
        // Forma primária: colar e definir via ReactSetter
        setReactInputValue(input, str);
        await new Promise(r => setTimeout(r, 50));
        
        // Verifica se a máscara engoliu a vírgula (ex: colou '53,5579' e ficou '535579')
        const currentVal = input.value || '';
        if (str.includes(',') && !currentVal.includes(',')) {
            // Limpa o campo
            setReactInputValue(input, '');
            await new Promise(r => setTimeout(r, 50));
            
            // Simulação hard de digitação
            for (let i = 0; i < str.length; i++) {
                const char = str[i];
                input.dispatchEvent(new KeyboardEvent('keydown', { key: char, bubbles: true }));
                input.dispatchEvent(new KeyboardEvent('keypress', { key: char, bubbles: true }));
                document.execCommand('insertText', false, char);
                input.dispatchEvent(new Event('input', { bubbles: true }));
                input.dispatchEvent(new KeyboardEvent('keyup', { key: char, bubbles: true }));
                await new Promise(r => setTimeout(r, 25));
            }
        }
    }

    function setReactInputValue(input, value) {
        if (!input) return false;

        input.focus();

        // 1. Simular Colar (Paste Event) - Fundamental para contornar máscaras de CPF, Data e Telefone
        try {
            const dataTransfer = new DataTransfer();
            dataTransfer.setData('text/plain', value);
            const pasteEvent = new ClipboardEvent('paste', {
                clipboardData: dataTransfer,
                bubbles: true,
                cancelable: true
            });
            input.dispatchEvent(pasteEvent);
        } catch (e) {
            console.error('Erro ao simular colar:', e);
        }

        // 2. Setar valor direto contornando a proteção de estado do React
        const lastValue = input.value;

        const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, "value")?.set;
        const nativeTextAreaValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, "value")?.set;
        const nativeSelectValueSetter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, "value")?.set;

        let setter = nativeInputValueSetter;
        if (input.tagName === 'TEXTAREA') setter = nativeTextAreaValueSetter;
        if (input.tagName === 'SELECT') setter = nativeSelectValueSetter;

        if (setter) {
            setter.call(input, value);
        } else {
            input.value = value;
        }

        // Atualizar o rastreador de valores do React (tracker) - Sempre atualizar se ele existir!
        const tracker = input._valueTracker;
        if (tracker) {
            tracker.setValue(lastValue);
        }

        // 3. Disparar eventos de alteração para sincronizar estados no React/Next.js
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));

        // 4. Simular teclas de confirmação
        input.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, key: 'Enter', code: 'Enter' }));
        input.dispatchEvent(new KeyboardEvent('keypress', { bubbles: true, key: 'Enter', code: 'Enter' }));
        input.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: 'Enter', code: 'Enter' }));

        input.blur();
        return true;
    }

    // Função de busca flexível por labels textuais (ignora elementos do assistente)
    function findInputByLabel(labelText) {
        const normalizedSearch = labelText.toLowerCase().trim();

        // 1. Busca por tags de label nativas ou customizadas (Material-UI)
        const labels = Array.from(document.querySelectorAll('label, legend, .MuiFormLabel-root, .MuiInputLabel-root, span.MuiFormLabel-root'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        for (const label of labels) {
            const text = label.textContent.toLowerCase();
            if (text.includes(normalizedSearch)) {
                // Via htmlFor
                if (label.htmlFor) {
                    const input = document.getElementById(label.htmlFor);
                    if (input) return input;
                }
                const forAttr = label.getAttribute('for');
                if (forAttr) {
                    const input = document.getElementById(forAttr);
                    if (input) return input;
                }
                // Input interno
                const innerInput = label.querySelector('input, select, textarea');
                if (innerInput) return innerInput;

                // Input irmão próximo ou dentro do container irmão
                let sibling = label.nextElementSibling;
                while (sibling) {
                    const input = sibling.querySelector('input, select, textarea') || (['INPUT', 'SELECT', 'TEXTAREA'].includes(sibling.tagName) ? sibling : null);
                    if (input) return input;
                    sibling = sibling.nextElementSibling;
                }

                // Subir um nível e procurar
                const parent = label.parentElement;
                if (parent) {
                    const input = parent.querySelector('input, select, textarea');
                    if (input) return input;
                }
            }
        }

        // 2. Busca por atributos nos próprios inputs (placeholder, aria-label, name, id)
        const inputs = Array.from(document.querySelectorAll('input, select, textarea'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        for (const input of inputs) {
            const placeholder = (input.getAttribute('placeholder') || '').toLowerCase();
            const name = (input.getAttribute('name') || '').toLowerCase();
            const ariaLabel = (input.getAttribute('aria-label') || '').toLowerCase();
            const id = (input.getAttribute('id') || '').toLowerCase();

            if (placeholder.includes(normalizedSearch) ||
                name.includes(normalizedSearch) ||
                ariaLabel.includes(normalizedSearch) ||
                id.includes(normalizedSearch)) {
                return input;
            }
        }

        return null;
    }

    // Busca apenas inputs ATIVOS (ignora os desabilitados de exibição na modal e no assistente)
    function findActiveInput(labelText) {
        const normalizedSearch = labelText.toLowerCase().trim();

        // Encontrar todos os inputs ativos na página (filtrando com isFieldDisabled)
        const allInputs = Array.from(document.querySelectorAll('input, select, textarea'))
            .filter(el => !isFieldDisabled(el) && !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));

        for (const input of allInputs) {
            const placeholder = (input.getAttribute('placeholder') || '').toLowerCase();
            const name = (input.getAttribute('name') || '').toLowerCase();
            const id = (input.getAttribute('id') || '').toLowerCase();
            const ariaLabel = (input.getAttribute('aria-label') || '').toLowerCase();

            // Encontrar texto do label associado
            let labelTextFound = '';
            const idVal = input.getAttribute('id');
            if (idVal) {
                const associatedLabel = document.querySelector(`[for="${idVal}"], label[for="${idVal}"]`);
                if (associatedLabel) labelTextFound = associatedLabel.textContent.toLowerCase();
            }
            if (!labelTextFound) {
                let parent = input.parentElement;
                while (parent && parent.tagName !== 'FORM' && parent.tagName !== 'BODY') {
                    const label = parent.querySelector('label, legend, .MuiFormLabel-root, .MuiInputLabel-root, [class*="label"], [class*="Label"]');
                    if (label) {
                        labelTextFound = label.textContent.toLowerCase();
                        break;
                    }
                    parent = parent.parentElement;
                }
            }

            if (placeholder.includes(normalizedSearch) ||
                name.includes(normalizedSearch) ||
                id.includes(normalizedSearch) ||
                ariaLabel.includes(normalizedSearch) ||
                labelTextFound.includes(normalizedSearch)) {
                return input;
            }
        }

        // Fallback para busca global se não achar nenhum ativo
        return findInputByLabel(labelText);
    }

    // Localiza especificamente o input ativo de CPF na tela (ignora assistente)
    function findCPFInput() {
        const directCpf = document.getElementById('cpfConsulta') || document.querySelector('input[name="cpf"]');
        if (directCpf && !isFieldDisabled(directCpf) && !directCpf.closest('#caf-assist-panel') && !directCpf.closest('#caf-info-modal')) {
            return directCpf;
        }
        const activeInputs = Array.from(document.querySelectorAll('input'))
            .filter(el => !isFieldDisabled(el) && !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        for (const input of activeInputs) {
            const name = (input.getAttribute('name') || '').toLowerCase();
            const id = (input.getAttribute('id') || '').toLowerCase();
            const placeholder = (input.getAttribute('placeholder') || '').toLowerCase();
            if (name.includes('cpf') || id.includes('cpf') || placeholder.includes('cpf')) {
                return input;
            }
        }
        return findActiveInput('CPF');
    }

    // Localiza especificamente o input ativo de Data de Nascimento na tela com estratégias avançadas (ignora assistente)
    function findBirthdateInput() {
        // 1. Procurar por input ativo do tipo nativo 'date'
        const nativeDate = Array.from(document.querySelectorAll('input[type="date"]'))
            .find(el => !isFieldDisabled(el) && !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        if (nativeDate) return nativeDate;

        // 2. Procurar por inputs de texto com atributos típicos ou placeholder DD/MM/AAAA
        const commonKeys = ['nasc', 'birth', 'data', 'date'];
        const activeInputs = Array.from(document.querySelectorAll('input'))
            .filter(el => !isFieldDisabled(el) && !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));

        for (const input of activeInputs) {
            const name = (input.getAttribute('name') || '').toLowerCase();
            const id = (input.getAttribute('id') || '').toLowerCase();
            const placeholder = (input.getAttribute('placeholder') || '').toLowerCase();

            if (placeholder.includes('dd') && placeholder.includes('mm') && placeholder.includes('aa')) return input;
            if (placeholder.includes('__/__/____')) return input;

            for (const key of commonKeys) {
                if ((name.includes(key) || id.includes(key)) && !name.includes('cpf') && !id.includes('cpf')) {
                    return input;
                }
            }
        }

        // 3. Fallback ordenado por labels associados comuns
        return findActiveInput('Nascimento') || findActiveInput('dd / mm / aaaa') || findActiveInput('dd/mm/aaaa') || findActiveInput('Data');
    }

    // Insere CPF contornando máscaras de forma extremamente robusta (padrão, dígitos puros e digitação simulada)
    async function fillCPFInput(input, cpfStr) {
        if (!input) return false;

        const rawCPF = cpfStr.replace(/\D/g, ''); // "07651541618"

        input.focus();
        setReactInputValue(input, '');
        await new Promise(resolve => setTimeout(resolve, 50));

        // 1. Tentar colar o CPF formatado completo
        setReactInputValue(input, cpfStr);
        await new Promise(resolve => setTimeout(resolve, 50));

        let digitsInInput = (input.value || '').replace(/\D/g, '');
        if (digitsInInput.length < 11) {
            console.log('Preenchimento de CPF formatado falhou, tentando dígitos puros...', rawCPF);
            setReactInputValue(input, '');
            await new Promise(resolve => setTimeout(resolve, 50));
            setReactInputValue(input, rawCPF);
            await new Promise(resolve => setTimeout(resolve, 50));
        }

        // 2. Se falhar, simular digitação caractere por caractere
        digitsInInput = (input.value || '').replace(/\D/g, '');
        if (digitsInInput.length < 11) {
            console.log('Preenchimento direto de CPF falhou, simulando digitação física...', rawCPF);
            setReactInputValue(input, '');
            await new Promise(resolve => setTimeout(resolve, 50));

            for (let char of rawCPF) {
                input.dispatchEvent(new KeyboardEvent('keydown', { key: char, code: `Digit${char}`, bubbles: true }));
                const curVal = input.value || '';
                setReactInputValue(input, curVal + char);
                input.dispatchEvent(new KeyboardEvent('keypress', { key: char, code: `Digit${char}`, bubbles: true }));
                input.dispatchEvent(new KeyboardEvent('keyup', { key: char, code: `Digit${char}`, bubbles: true }));
                await new Promise(resolve => setTimeout(resolve, 30));
            }
        }

        input.blur();
        return true;
    }

    // Insere Data de Nascimento contornando máscaras e data nativa (padrão, dígitos puros e digitação simulada)
    async function fillDateInput(input, dateStr) {
        if (!input) return false;

        // Determinar o formato correto do input
        const isNativeDate = input.type === 'date' || input.getAttribute('type') === 'date';

        // Se a data já contiver barras (DD/MM/YYYY) ou traços (YYYY-MM-DD), normalizar
        let dateYYYYMMDD = '';
        let dateDDMMYYYY = '';

        if (dateStr.includes('-')) {
            // Se veio como YYYY-MM-DD
            dateYYYYMMDD = dateStr;
            const parts = dateStr.split('-');
            dateDDMMYYYY = `${parts[2]}/${parts[1]}/${parts[0]}`;
        } else if (dateStr.includes('/')) {
            // Se veio como DD/MM/YYYY
            dateDDMMYYYY = dateStr;
            const parts = dateStr.split('/');
            dateYYYYMMDD = `${parts[2]}-${parts[1]}-${parts[0]}`;
        } else {
            // Sem separadores, assumir YYYYMMDD ou DDMMYYYY
            if (dateStr.length === 8) {
                dateDDMMYYYY = `${dateStr.substring(0, 2)}/${dateStr.substring(2, 4)}/${dateStr.substring(4)}`;
                dateYYYYMMDD = `${dateStr.substring(4)}-${dateStr.substring(2, 4)}-${dateStr.substring(0, 2)}`;
            } else {
                dateYYYYMMDD = dateStr;
                dateDDMMYYYY = dateStr;
            }
        }

        if (isNativeDate) {
            // Input nativo de data requer especificamente o formato YYYY-MM-DD
            setReactInputValue(input, dateYYYYMMDD);
            return true;
        }

        const rawDigits = dateDDMMYYYY.replace(/\D/g, ''); // Ex: "01061985"

        input.focus();
        input.select();
        await new Promise(resolve => setTimeout(resolve, 50));

        // Tentar preencher com execCommand (simula cola/digitação natural que respeita máscaras React/MUI)
        document.execCommand('insertText', false, dateDDMMYYYY);
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        await new Promise(resolve => setTimeout(resolve, 50));

        let digitsInInput = (input.value || '').replace(/\D/g, '');
        
        // Se ainda falhar, tentar dígito por dígito via execCommand
        if (digitsInInput.length < 8) {
            console.log('Primeira tentativa de data falhou. Tentando dígito por dígito via execCommand...', rawDigits);
            input.focus();
            input.select();
            document.execCommand('insertText', false, ''); // Limpa
            for (let char of rawDigits) {
                document.execCommand('insertText', false, char);
                await new Promise(resolve => setTimeout(resolve, 15));
            }
            input.dispatchEvent(new Event('input', { bubbles: true }));
        }

        input.blur();
        return true;
    }

    // Encontra botão pelo texto com suporte a busca exata e parcial robusta (ignora elementos do assistente)
    function findButtonByText(text, exactOnly = false) {
        const normalizedSearch = text.toUpperCase().trim();
        const elements = Array.from(document.querySelectorAll('button, span, a, input[type="button"], input[type="submit"]'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal') && el.offsetWidth > 0);

        // 1. Busca exata prioritária
        for (const el of elements) {
            const elText = el.textContent.trim().toUpperCase();
            const valAttr = (el.getAttribute('value') || '').toUpperCase().trim();
            if (elText === normalizedSearch || valAttr === normalizedSearch) {
                return el.tagName === 'BUTTON' ? el : el.closest('button') || el;
            }
        }

        if (exactOnly) return null;

        // Palavras proibidas caso a busca seja por "ADICIONAR" ou "INCLUIR" simples
        const forbiddenIfGeneric = ['ENDERECO', 'ENDEREÇO', 'TELEFONE', 'AREA', 'ÁREA', 'RENDA', 'PRODUTO', 'IMOVEL', 'IMÓVEL', 'DOCUMENTO', 'ANEXO', 'ARQUIVO'];

        // 2. Busca parcial como fallback secundário (ex: botões com ícones)
        for (const el of elements) {
            const elText = el.textContent.toUpperCase().trim();
            const valAttr = (el.getAttribute('value') || '').toUpperCase().trim();
            
            // Se a busca é genérica por "ADICIONAR", não aceita botões com substantivos específicos como "ADICIONAR ENDEREÇO"
            if (normalizedSearch === 'ADICIONAR' || normalizedSearch === 'INCLUIR') {
                if (forbiddenIfGeneric.some(w => elText.includes(w) || valAttr.includes(w))) {
                    continue;
                }
            }

            if (elText.includes(normalizedSearch) || valAttr.includes(normalizedSearch)) {
                return el.tagName === 'BUTTON' ? el : el.closest('button') || el;
            }
        }
        return null;
    }

    // Localiza e abre o formulário de Membro / Composição Familiar via Popover Menu ou Botão Direto
    async function abrirFormularioMembro() {
        // 1. Se o campo de consulta já estiver ativo na tela, retorna imediatamente
        if (document.getElementById('cpfConsulta')) return true;

        // 2. Se o Popover Menu já estiver aberto no DOM (<li role="menuitem"> com "Adicionar" ou data-testid="AddIcon")
        const menuItems = Array.from(document.querySelectorAll('li[role="menuitem"], .MuiMenuItem-root'))
            .filter(li => !li.closest('#caf-assist-panel') && !li.closest('#caf-info-modal') && li.offsetWidth > 0);

        const addMenuItem = menuItems.find(li => {
            const txt = (li.textContent || '').trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
            const hasAddIcon = !!li.querySelector('[data-testid="AddIcon"]');
            return (txt === 'adicionar' || hasAddIcon) && !txt.includes('endereco') && !txt.includes('telefone');
        });

        if (addMenuItem) {
            console.log('[CAF] Clicando no item do menu Popover: Adicionar Membro...');
            addMenuItem.click();
            await waitForLoader();
            await sleep(600);
            return !!document.getElementById('cpfConsulta');
        }

        // 3. Se o Popover Menu ainda não estiver aberto, localizar o botão que abre o menu na seção de Grupo Familiar
        const cardsMembros = Array.from(document.querySelectorAll('.MuiCard-root, .MuiPaper-root, .MuiGrid-root, div'))
            .filter(c => {
                if (c.closest('#caf-assist-panel') || c.closest('#caf-info-modal')) return false;
                const txt = (c.textContent || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                return (txt.includes('grupo familiar') || txt.includes('membros') || txt.includes('composicao familiar')) &&
                       !txt.includes('endereco de residencia') && !txt.includes('endereco');
            });

        let btnMenu = null;

        for (const card of cardsMembros) {
            const btns = Array.from(card.querySelectorAll('button, .MuiIconButton-root, .MuiButton-root'))
                .filter(b => !b.closest('#caf-assist-panel') && !b.closest('#caf-info-modal') && b.offsetWidth > 0);

            btnMenu = btns.find(b => {
                const aria = (b.getAttribute('aria-label') || '').toLowerCase();
                const hasMenuPopup = b.getAttribute('aria-haspopup') === 'menu' || b.getAttribute('aria-haspopup') === 'true';
                const hasIcon = !!b.querySelector('[data-testid="MoreVertIcon"], [data-testid="MoreHorizIcon"], [data-testid="AddIcon"], [data-testid="AddCircleOutlineIcon"]');
                return hasMenuPopup || hasIcon || aria.includes('acoes') || aria.includes('opcoes') || aria.includes('adicionar');
            });

            if (btnMenu) break;
        }

        // Se não achou dentro dos cards filtrados, procurar globalmente botões de menu que NÃO pertençam a Endereço
        if (!btnMenu) {
            const globalActionBtns = Array.from(document.querySelectorAll('button[aria-haspopup="menu"], button[aria-haspopup="true"], .MuiIconButton-root'))
                .filter(b => !b.closest('#caf-assist-panel') && !b.closest('#caf-info-modal') && b.offsetWidth > 0);

            btnMenu = globalActionBtns.find(b => {
                const parent = b.closest('.MuiGrid-root, .MuiBox-root, div');
                const parentTxt = (parent?.textContent || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                return !parentTxt.includes('endereco de residencia') && !parentTxt.includes('endereco');
            });
        }

        if (btnMenu) {
            console.log('[CAF] Acionando menu de ações do Grupo Familiar...');
            btnMenu.click();
            await sleep(300);

            // Clica no item "Adicionar" do menu que acabou de surgir
            const newlyOpenedItem = Array.from(document.querySelectorAll('li[role="menuitem"], .MuiMenuItem-root'))
                .find(li => {
                    const txt = (li.textContent || '').trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                    const hasAddIcon = !!li.querySelector('[data-testid="AddIcon"]');
                    return (txt === 'adicionar' || hasAddIcon) && !txt.includes('endereco');
                });

            if (newlyOpenedItem) {
                console.log('[CAF] Clicando no item Adicionar do menu recém-aberto...');
                newlyOpenedItem.click();
                await waitForLoader();
                await sleep(600);
                return !!document.getElementById('cpfConsulta');
            }
        }

        // 4. Fallback direto: Botão com texto explícito de membro que não seja de endereço
        const btnDireto = Array.from(document.querySelectorAll('button, .MuiButton-root'))
            .filter(b => !b.closest('#caf-assist-panel') && !b.closest('#caf-info-modal') && b.offsetWidth > 0)
            .find(b => {
                const txt = (b.textContent || '').trim().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                const parentTxt = (b.closest('.MuiBox-root, .MuiGrid-root, div')?.textContent || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                if (parentTxt.includes('endereco de residencia') || txt.includes('endereco')) return false;
                return txt.includes('adicionar membro') || txt.includes('incluir membro') || (txt === 'adicionar' && !parentTxt.includes('endereco'));
            });

        if (btnDireto) {
            console.log('[CAF] Clicando no botão direto de Adicionar Membro...');
            btnDireto.click();
            await waitForLoader();
            await sleep(600);
            return !!document.getElementById('cpfConsulta');
        }

        return false;
    }

    // Clica em um Radio Button pelo rótulo do grupo e o texto do valor (ignora assistente)
    function clickRadio(groupLabel, valueText) {
        const normalizedGroup = groupLabel.trim().toLowerCase();
        const normalizedValue = valueText.trim().toLowerCase();

        // 1. Suporte direto a nomes de campos de Radio nativos do CAF 2026
        let radioName = '';
        if (normalizedGroup.includes('mão de obra') || normalizedGroup.includes('trabalhaufpa') || normalizedGroup.includes('trabalha')) {
            radioName = 'trabalhaUfpa';
        } else if (normalizedGroup.includes('agroecol') || normalizedGroup.includes('producaoagroecologica')) {
            radioName = 'producaoAgroecologica';
        } else if (normalizedGroup.includes('imóvel principal') || normalizedGroup.includes('imovelprincipal')) {
            radioName = 'imovelPrincipal';
        }

        if (radioName) {
            let valAttr = '';
            if (radioName === 'trabalhaUfpa') valAttr = (normalizedValue === 'sim' || normalizedValue === '1') ? '1' : '2';
            else if (radioName === 'producaoAgroecologica') valAttr = (normalizedValue === 'sim' || normalizedValue === '1') ? '1' : '0';
            else if (radioName === 'imovelPrincipal') valAttr = (normalizedValue === 'sim' || normalizedValue === 'true') ? 'true' : 'false';

            const directRadio = document.querySelector(`input[name="${radioName}"][value="${valAttr}"]`);
            if (directRadio) {
                const clickable = directRadio.closest('label') || directRadio;
                clickable.click();
                highlightField(clickable, 'success');
                return true;
            }
        }

        // 2. Encontrar containers contendo groupLabel
        const containers = Array.from(document.querySelectorAll('.MuiFormControl-root, fieldset, div'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        for (const container of containers) {
            const text = container.textContent || '';
            if (text.toLowerCase().includes(normalizedGroup)) {
                const labels = Array.from(container.querySelectorAll('label, .MuiFormControlLabel-root'));
                for (const label of labels) {
                    if (label.textContent.trim().toLowerCase() === normalizedValue) {
                        const input = label.querySelector('input[type="radio"]') || label;
                        input.click();
                        highlightField(label, 'success');
                        return true;
                    }
                }
            }
        }

        // Fallback global por textos exatos de labels
        const labels = Array.from(document.querySelectorAll('label, .MuiFormControlLabel-root, span.MuiFormControlLabel-label'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        for (const label of labels) {
            if (label.textContent.trim().toLowerCase() === normalizedValue) {
                const clickable = label.closest('label') || label.querySelector('input[type="radio"]') || label;
                clickable.click();
                highlightField(clickable, 'success');
                return true;
            }
        }

        return false;
    }

    // Normalização e correspondência inteligente de textos de opções do CAF
    function matchOptionText(optionText, searchPattern, labelPattern = '') {
        const opt = optionText.toLowerCase().trim()
            .normalize("NFD").replace(/[\u0300-\u036f]/g, ""); // Remove acentuação
        const search = searchPattern.toLowerCase().trim()
            .normalize("NFD").replace(/[\u0300-\u036f]/g, ""); // Remove acentuação

        const isUF = labelPattern.toLowerCase().includes('uf');

        if (isUF) {
            const searchUpper = searchPattern.toUpperCase().trim();
            // Se pesquisou por sigla (Ex: "MG"), tentar converter para o nome completo do estado
            if (ufNames[searchUpper]) {
                const fullName = ufNames[searchUpper].toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                if (opt === search.toLowerCase() || opt === fullName || opt.includes(fullName) || opt.includes(search.toLowerCase())) {
                    return true;
                }
            }
            // Se a opção contiver a sigla em parênteses ou delimitada (Ex: "Minas Gerais (MG)" ou "Minas Gerais - MG")
            if (opt.includes(`(${search})`) || opt.includes(`- ${search}`) || opt.endsWith(` ${search}`)) {
                return true;
            }
        }

        // 1. Igualdade exata após normalização
        if (opt === search) return true;

        // 2. Remove sufixos comuns de gênero de documentos/opções (Ex: Casado(a) -> Casado)
        const cleanOpt = opt.replace(/\(a\)/g, '').replace(/\(o\)/g, '').replace(/\(a\/o\)/g, '').trim();
        const cleanSearch = search.replace(/\(a\)/g, '').replace(/\(o\)/g, '').replace(/\(a\/o\)/g, '').trim();
        if (cleanOpt === cleanSearch) return true;

        // 3. Correspondência parcial inteligente
        if (cleanOpt.includes(cleanSearch) || cleanSearch.includes(cleanOpt)) return true;

        // 4. Casos especiais para Escolaridade (Ensino Fundamental, Médio, Superior, etc.)
        if (search.includes('fund') && opt.includes('fundamental')) {
            if (search.includes('incomp') && opt.includes('incompleto')) return true;
            if (search.includes('comp') && opt.includes('completo')) return true;
        }
        if (search.includes('medi') && opt.includes('medio')) {
            if (search.includes('incomp') && opt.includes('incompleto')) return true;
            if (search.includes('comp') && opt.includes('completo')) return true;
        }
        if (search.includes('super') && opt.includes('superior')) {
            if (search.includes('incomp') && opt.includes('incompleto')) return true;
            if (search.includes('comp') && opt.includes('completo')) return true;
        }
        if (search.includes('nao alf') && (opt.includes('nao alf') || opt.includes('sem instru'))) return true;
        if (search.includes('sem instru') && (opt.includes('nao alf') || opt.includes('sem instru'))) return true;
        if (search.includes('alfa') && opt.includes('alfabetizado') && !search.includes('nao') && !opt.includes('nao')) return true;

        // 5. Casos especiais para Relação de Parentesco (Lista Oficial CAF 2026)
        if (search.includes('conjuge') && (opt.includes('conjuge') || opt.includes('companheiro'))) return true;
        if (search.includes('companheiro') && (opt.includes('conjuge') || opt.includes('companheiro'))) return true;
        if (search.includes('filho') && (opt.includes('filho') || opt.includes('filha'))) return true;
        if (search.includes('enteado') && (opt.includes('enteado') || opt.includes('enteada'))) return true;
        if (search.includes('pai') && (opt.includes('pai') || opt.includes('mae'))) return true;
        if (search.includes('mae') && (opt.includes('pai') || opt.includes('mae'))) return true;
        if (search.includes('irma') && (opt.includes('irma') || opt.includes('irmao'))) return true;
        if (search.includes('neto') && (opt.includes('neto') || opt.includes('neta') || opt.includes('bisneto'))) return true;
        if (search.includes('bisneto') && (opt.includes('neto') || opt.includes('neta') || opt.includes('bisneto'))) return true;
        if (search.includes('sogro') && (opt.includes('sogro') || opt.includes('sogra'))) return true;
        if (search.includes('genro') && (opt.includes('genro') || opt.includes('nora'))) return true;
        if (search.includes('nora') && (opt.includes('genro') || opt.includes('nora'))) return true;
        if (search.includes('nao parente') && opt.includes('nao parente')) return true;
        if (search.includes('outro') && opt.includes('outro')) return true;

        // 6. Casos especiais para Raça/Cor
        if (search === 'pardo' && opt === 'parda') return true;
        if (search === 'parda' && opt === 'pardo') return true;
        if (search === 'branco' && opt === 'branca') return true;
        if (search === 'branca' && opt === 'branco') return true;
        if (search === 'preto' && opt === 'preta') return true;
        if (search === 'preta' && opt === 'preto') return true;
        if (search === 'amarelo' && opt === 'amarela') return true;
        if (search === 'amarela' && opt === 'amarelo') return true;
        if (search === 'indigena' && opt === 'indigena') return true;
        if (search.includes('nao inform') && (opt.includes('nao declar') || opt.includes('sem declar') || opt.includes('nao inform'))) return true;
        if (search.includes('nao declar') && (opt.includes('nao declar') || opt.includes('sem declar') || opt.includes('nao inform'))) return true;

        return false;
    }

    // Localiza de forma flexível o input/select correspondente a um label (ignora assistente)
    function findMUIField(labelPattern) {
        const normalizedSearch = labelPattern.toLowerCase().trim();

        // 1. Busca direta por ID ou Name exato (CAF 2026)
        const directEl = document.getElementById(labelPattern) || document.querySelector(`[name="${labelPattern}"]`);
        if (directEl && !directEl.closest('#caf-assist-panel') && !directEl.closest('#caf-info-modal')) {
            if (directEl.tagName === 'INPUT' || directEl.tagName === 'SELECT' || directEl.getAttribute('role') === 'combobox' || directEl.getAttribute('role') === 'button' || directEl.className.includes('MuiSelect-select')) {
                return directEl;
            }
            const container = directEl.closest('.MuiFormControl-root') || directEl.parentElement;
            if (container) {
                const inner = container.querySelector('input, [role="combobox"], [role="button"], .MuiSelect-select, select');
                if (inner) return inner;
            }
        }

        const labels = Array.from(document.querySelectorAll('label, .MuiFormLabel-root, .MuiInputLabel-root, span.MuiFormLabel-root'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));

        for (const label of labels) {
            if (label.textContent.toLowerCase().includes(normalizedSearch)) {
                // Procurar no mesmo container MuiFormControl ou elemento pai
                const container = label.closest('.MuiFormControl-root') || label.parentElement;
                if (container) {
                    const field = container.querySelector('input, [role="combobox"], [role="button"], .MuiSelect-select, select');
                    if (field) return field;
                }

                // Fallback: buscar irmãos próximos
                let sibling = label.nextElementSibling;
                while (sibling) {
                    const field = sibling.querySelector('input, [role="combobox"], [role="button"], .MuiSelect-select, select') ||
                        (sibling.tagName === 'INPUT' || sibling.getAttribute('role') === 'combobox' || sibling.getAttribute('role') === 'button' ? sibling : null);
                    if (field) return field;
                    sibling = sibling.nextElementSibling;
                }
            }
        }

        // Fallback secundário global por metadados do próprio campo
        const allFields = Array.from(document.querySelectorAll('input, select, [role="combobox"], [role="button"], .MuiSelect-select'))
            .filter(el => !el.closest('#caf-assist-panel') && !el.closest('#caf-info-modal'));
        for (const field of allFields) {
            const placeholder = (field.getAttribute('placeholder') || '').toLowerCase();
            const name = (field.getAttribute('name') || '').toLowerCase();
            const id = (field.getAttribute('id') || '').toLowerCase();
            const ariaLabel = (field.getAttribute('aria-label') || '').toLowerCase();

            if (placeholder.includes(normalizedSearch) ||
                name.includes(normalizedSearch) ||
                id.includes(normalizedSearch) ||
                ariaLabel.includes(normalizedSearch)) {
                return field;
            }
        }

        return null;
    }

    // =========================================================================
    // SIMULADOR DE TECLADO E CLIQUE (MÉTODO DO EXTRATOR)
    // =========================================================================
    function simularTecla(keyName, keyCode, alvo) {
        let el = alvo || document.activeElement || document.body;
        let eventDown = new KeyboardEvent('keydown', {
            key: keyName, code: keyName, keyCode: keyCode, which: keyCode,
            bubbles: true, cancelable: true
        });
        el.dispatchEvent(eventDown);
    }

    async function abrirCaixa(elemento) {
        elemento.focus();
        if (elemento.tagName.toLowerCase() === 'input') {
            let container = elemento.closest('.MuiFormControl-root');
            let btnSeta = container ? container.querySelector('.MuiAutocomplete-popupIndicator') : null;
            if (btnSeta) {
                btnSeta.click();
            } else {
                elemento.click();
                simularTecla('ArrowDown', 40, elemento);
            }
        } else {
            elemento.click();
            simularTecla(' ', 32, elemento);
        }

        // Aguarda a lista aparecer
        for (let i = 0; i < 20; i++) {
            if (document.querySelector('[role="listbox"]')) return true;
            await new Promise(resolve => setTimeout(resolve, 150));
        }
        return false;
    }

    // Função inteligente e infalível para preencher dropdowns (Material-UI Select, Autocomplete ou Nativo)
    async function selectOption(labelPattern, targetOptionText) {
        if (!targetOptionText) return false;

        const field = findMUIField(labelPattern);
        if (!field) {
            console.warn(`Campo não localizado para o rótulo: ${labelPattern}`);
            return false;
        }

        // Caso 1: SELECT nativo HTML
        if (field.tagName === 'SELECT') {
            const optionToSelect = Array.from(field.options).find(opt =>
                matchOptionText(opt.text, targetOptionText, labelPattern) || matchOptionText(opt.value, targetOptionText, labelPattern)
            );
            if (optionToSelect) {
                setReactInputValue(field, optionToSelect.value);
                highlightField(field, 'success');
                return true;
            }
            return false;
        }

        // Caso 2: MUI Autocomplete (Input com role combobox, comumente usado para UF e Município de Nascimento)
        const isAutocomplete = field.tagName === 'INPUT' &&
            (field.getAttribute('role') === 'combobox' ||
                field.getAttribute('autocomplete') === 'off' ||
                field.className.includes('MuiAutocomplete-input'));

        if (isAutocomplete) {
            console.log(`[CAF] Preenchendo Autocomplete de ${labelPattern} com: ${targetOptionText}`);
            field.focus();

            // 1. Limpar valor anterior para evitar acúmulos
            setReactInputValue(field, '');
            await new Promise(resolve => setTimeout(resolve, 100));

            // 2. Digitar o texto da opção desejada no input para filtrar a listagem do React/Next.js
            setReactInputValue(field, targetOptionText);
            await new Promise(resolve => setTimeout(resolve, 150));

            // 3. Forçar abertura da listbox usando o método do Extrator
            const abriu = await abrirCaixa(field);
            if (!abriu) {
                console.warn(`[CAF] Popup do Autocomplete para '${labelPattern}' não abriu.`);
                return false;
            }

            await new Promise(resolve => setTimeout(resolve, 250)); // Esperar debounce do Next/React

            // 4. Buscar e clicar na opção que apareceu na tela
            const options = Array.from(document.querySelectorAll('[role="listbox"] [role="option"], li[role="option"], .MuiAutocomplete-option, .MuiMenuItem-root, [role="listbox"] li'));

            if (options.length > 0) {
                const matchedOption = options.find(opt => matchOptionText(opt.textContent, targetOptionText, labelPattern));
                if (matchedOption) {
                    matchedOption.scrollIntoView({ block: 'nearest' });
                    // MUI e React exigem evento de mousedown + clique físico na opção
                    matchedOption.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
                    matchedOption.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
                    matchedOption.click();
                    highlightField(field, 'success');
                    return true;
                } else {
                    console.log(`[CAF] Rótulo '${targetOptionText}' não bateu com as opções:`, options.map(o => o.textContent));
                }
            } else {
                console.warn(`[CAF] Popup do Autocomplete para '${labelPattern}' não exibiu opções.`);
            }

            // Fechar o popup se ainda estiver aberto para não travar a UI
            simularTecla('Escape', 27, field);
            return false;
        }

        // Caso 3: MUI Select (DIV customizado que atua como select trigger)
        let selectTrigger = field;
        if (field.tagName === 'INPUT') {
            const container = field.parentElement;
            if (container) {
                selectTrigger = container.querySelector('[role="button"], [role="combobox"], .MuiSelect-select') || field;
            }
        }

        if (selectTrigger) {
            console.log(`[CAF] Preenchendo MUI Select ${labelPattern} com: ${targetOptionText}`);

            // Forçar abertura da listbox usando o método do Extrator
            const abriu = await abrirCaixa(selectTrigger);
            if (!abriu) {
                console.warn(`[CAF] Popup de opções para '${labelPattern}' não abriu.`);
                return false;
            }

            highlightField(selectTrigger, 'warning');

            // Aguardar a renderização do portal popover no final do body
            await new Promise(resolve => setTimeout(resolve, 200));

            const options = Array.from(document.querySelectorAll('[role="listbox"] [role="option"], li[role="option"], .MuiMenuItem-root, [role="listbox"] li'));
            if (options.length > 0) {
                const matchedOption = options.find(opt => matchOptionText(opt.textContent, targetOptionText, labelPattern));
                if (matchedOption) {
                    matchedOption.scrollIntoView({ block: 'nearest' });

                    // Simular fluxo de clique completo reconhecido pelo React
                    matchedOption.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
                    matchedOption.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
                    matchedOption.click();

                    highlightField(selectTrigger, 'success');
                    return true;
                } else {
                    console.log(`[CAF] Nenhuma opção correspondente para '${targetOptionText}' em:`, options.map(o => o.textContent));
                }
            } else {
                console.warn(`[CAF] Popover de opções para '${labelPattern}' não foi localizado.`);
            }

            // Fechar enviando Escape global
            simularTecla('Escape', 27, selectTrigger);
        }
        return false;
    }

    // Dar um destaque visual piscante no campo preenchido
    function highlightField(element, type = 'success') {
        if (!element) return;
        const originalBorder = element.style.border;
        const originalShadow = element.style.boxShadow;
        const originalTransition = element.style.transition;

        element.style.transition = 'all 0.25s ease';

        if (type === 'success') {
            element.style.border = '2px solid #10b981';
            element.style.boxShadow = '0 0 10px rgba(16, 185, 129, 0.5)';
        } else if (type === 'warning') {
            element.style.border = '2px solid #fbbf24';
            element.style.boxShadow = '0 0 10px rgba(245, 158, 11, 0.5)';
        }

        setTimeout(() => {
            element.style.border = originalBorder;
            element.style.boxShadow = originalShadow;
            element.style.transition = originalTransition;
        }, 2000);
    }

    // Mostrar feedback Toast elegante na tela
    function showToast(message, success = true) {
        const toast = document.getElementById('caf-toast');
        if (!toast) return;

        toast.style.background = success ? 'rgba(16, 185, 129, 0.95)' : 'rgba(239, 68, 68, 0.95)';
        toast.innerHTML = `
            <span style="font-size: 16px;">${success ? '⚡' : '❌'}</span>
            <span>${message}</span>
        `;

        toast.classList.add('show');
        setTimeout(() => {
            toast.classList.remove('show');
        }, 3000);
    }

    // Copiar texto para o clipboard de forma segura
    function copyToClipboard(text, label) {
        if (typeof GM_setClipboard !== 'undefined') {
            GM_setClipboard(text);
        } else {
            const el = document.createElement('textarea');
            el.value = text;
            document.body.appendChild(el);
            el.select();
            document.execCommand('copy');
            document.body.removeChild(el);
        }
        showToast(`Copiado: ${label}`);
    }

    // Formatar data YYYY-MM-DD para DD/MM/YYYY
    function formatDate(dateStr) {
        if (!dateStr) return '';
        if (dateStr.includes('/')) return dateStr; // Já está formatada
        const parts = dateStr.split('-');
        if (parts.length === 3) {
            return `${parts[2]}/${parts[1]}/${parts[0]}`;
        }
        return dateStr;
    }

    // Formatar telefone
    function formatPhone(phoneStr) {
        if (!phoneStr) return '';
        const cleaned = phoneStr.replace(/\D/g, '');
        if (cleaned.length === 11) {
            return `(${cleaned.substring(0, 2)}) ${cleaned.substring(2, 7)}-${cleaned.substring(7)}`;
        } else if (cleaned.length === 10) {
            return `(${cleaned.substring(0, 2)}) ${cleaned.substring(2, 6)}-${cleaned.substring(6)}`;
        }
        return phoneStr;
    }

