async function inserirTodosProdutos() {
    if (!loadedData || !loadedData.produtos) return;

    for (let i = 0; i < loadedData.produtos.length; i++) {
        showToast(`Inserindo produto ${i + 1} de ${loadedData.produtos.length}...`, true);

        const sucesso = await inserirProdutoUnico(loadedData.produtos[i], true);

        if (sucesso) {
            // Se confirmou na tabela, basta um respiro ínfimo de 400ms para o React não engasgar
            // e já pula pro próximo "Adicionar"
            await sleep(400);
        } else {
            // Se falhou (timeout), loga o aviso, mas continua pro próximo
            showToast(`Atenção: Produto ${i + 1} estourou o tempo de salvamento.`, false);
            await sleep(1000);
        }
    }
    showToast('Todos os produtos foram processados com sucesso!', true);
}
// Função Mestra para aguardar o carregamento (Spinner) da página sumir
async function waitForLoader() {
    for (let i = 0; i < 100; i++) { // Espera até 20 segundos em redes lentas
        const loaders = Array.from(document.querySelectorAll('.MuiBackdrop-root')).filter(b => b.querySelector('.MuiCircularProgress-root'));

        if (loaders.length === 0) break; // Não tem loader na tela

        const algumVisivel = loaders.some(loader => {
            const style = window.getComputedStyle(loader);
            return style.opacity !== '0' && style.visibility !== 'hidden' && loader.style.display !== 'none';
        });

        if (!algumVisivel) break; // O loader apagou da tela!

        await sleep(200);
    }
    await sleep(100); // Fôlego para o React processar o fim do loader
}

// Helper para localizar o item de menu "Adicionar" (role="menuitem") no MUI Popover
function findAddMenuItem() {
    // 1. Procurar elementos com role="menuitem" ou classe .MuiMenuItem-root
    const items = Array.from(document.querySelectorAll('[role="menuitem"], .MuiMenuItem-root, li.MuiMenuItem-root'));
    for (const item of items) {
        const text = (item.textContent || '').trim().toLowerCase();
        const hasAddIcon = !!item.querySelector('[data-testid="AddIcon"]');
        if (hasAddIcon || text === 'adicionar' || text.startsWith('adicionar')) {
            return item;
        }
    }

    // 2. Fallback em popovers/menus MUI
    const popovers = Array.from(document.querySelectorAll('.MuiPopover-paper, .MuiMenu-paper, [role="menu"]'));
    for (const popover of popovers) {
        const els = Array.from(popover.querySelectorAll('li, [role="menuitem"], div, span'));
        for (const el of els) {
            const text = (el.textContent || '').trim().toLowerCase();
            if (text === 'adicionar') {
                return el.closest('li') || el.closest('[role="menuitem"]') || el;
            }
        }
    }

    return null;
}

async function acionarBotaoAdicionarRenda() {
    // 1. Verificar se a janela modal de produto já está aberta
    const inputProdutoExistente = document.getElementById('idProduto');
    const inputEstimadaExistente = document.getElementById('rendaEstimada');
    if (inputProdutoExistente || inputEstimadaExistente) {
        return true;
    }

    // 2. Se o menu popover MUI com "Adicionar" já estiver aberto na tela, clica diretamente nele
    let addMenuItem = findAddMenuItem();
    if (addMenuItem) {
        console.log('[CAF] Menu popover "Adicionar" já estava visível. Clicando...');
        addMenuItem.click();
        await waitForLoader();
    if (cafAbort) return false;
        return true;
    }

    // ETAPA 1: Clicar / Expandir "Rendas do Estabelecimento" caso não esteja visível
    const accordionSummaries = Array.from(document.querySelectorAll('.MuiAccordionSummary-root, .MuiAccordionSummary-content'));
    const accordionRendas = accordionSummaries.find(el => {
        const txt = (el.textContent || '').toLowerCase();
        return txt.includes('rendas do estabelecimento') && !txt.includes('fora do estabelecimento');
    });

    if (accordionRendas) {
        const parentAccordion = accordionRendas.closest('.MuiAccordion-root');
        if (parentAccordion && !parentAccordion.classList.contains('Mui-expanded') && accordionRendas.getAttribute('aria-expanded') !== 'true') {
            console.log('[CAF] (Etapa 1) Expandindo sanfona Rendas do Estabelecimento...');
            accordionRendas.click();
            await sleep(300);
        }
    }

    // ETAPA 2: Clicar no botão "Ações" (MuiButton com texto Ações ou aria-haspopup="true")
    const allBtns = Array.from(document.querySelectorAll('button, .MuiButton-root, [role="button"]'))
        .filter(b => !b.closest('#caf-assist-panel') && !b.closest('#caf-info-modal'));

    let btnAcoes = allBtns.find(b => {
        const txt = (b.textContent || '').trim().toLowerCase();
        const grandParentTxt = (b.closest('.MuiPaper-root, .MuiAccordion-root, section') ? b.closest('.MuiPaper-root, .MuiAccordion-root, section').textContent || '' : '').toLowerCase();

        const isAcoes = txt === 'ações' || txt === 'acoes' || txt.includes('ações');
        const isNoContainerRendas = grandParentTxt.includes('rendas do estabelecimento') && !grandParentTxt.includes('fora do estabelecimento');

        return isAcoes && (isNoContainerRendas || b.getAttribute('aria-haspopup') === 'true');
    });

    // Fallback: Qualquer botão de texto 'Ações' na tela
    if (!btnAcoes) {
        btnAcoes = allBtns.find(b => {
            const txt = (b.textContent || '').trim().toLowerCase();
            return txt === 'ações' || txt === 'acoes';
        });
    }

    if (btnAcoes) {
        console.log('[CAF] (Etapa 2) Clicando no botão "Ações"...', btnAcoes);
        btnAcoes.focus();
        btnAcoes.click();
        await sleep(300); // Aguarda a transição/abertura do MUI Popover
    } else {
        console.warn('[CAF] Botão Ações não localizado por texto simples. Procurando por acionador de popover...');
        const containers = Array.from(document.querySelectorAll('.MuiPaper-root, .MuiCard-root, fieldset, div, section'))
            .filter(el => {
                const txt = (el.textContent || '').toLowerCase();
                return txt.includes('rendas do estabelecimento') && !txt.includes('fora do estabelecimento');
            });

        for (const container of containers) {
            const btns = Array.from(container.querySelectorAll('button, [role="button"], .MuiIconButton-root'));
            const triggerBtn = btns.find(b => b.getAttribute('aria-haspopup') === 'true' || b.querySelector('[data-testid="ArrowDropDownIcon"]'));
            if (triggerBtn) {
                triggerBtn.click();
                await sleep(300);
                break;
            }
        }
    }

    // ETAPA 3: Aguardar o menu popover abrir e clicar no item "Adicionar" (role="menuitem")
    for (let i = 0; i < 20; i++) {
        addMenuItem = findAddMenuItem();
        if (addMenuItem) {
            console.log('[CAF] (Etapa 3) Item "Adicionar" (role=menuitem) localizado no menu popover! Clicando...');
            addMenuItem.click();
            await waitForLoader();
    if (cafAbort) return false;
            return true;
        }
        await sleep(150);
    }

    return false;
}

// Helper para fechar avisos/dialogs de confirmação (ex: "Atualização de documento comprobatório de Renda")
async function fecharAvisoComprobatorioRenda() {
    const dialogs = Array.from(document.querySelectorAll('[role="dialog"], .MuiDialog-paper'));
    const dialogAviso = dialogs.find(d => {
        const txt = (d.textContent || '').toLowerCase();
        return txt.includes('atualização de documento comprobatório') ||
            txt.includes('novo documento comprobatório') ||
            txt.includes('após incluir nova renda');
    });

    if (dialogAviso) {
        console.log('[CAF] (Etapa 4) Diálogo de aviso sobre documento comprobatório de Renda detectado!');
        const btnOk = Array.from(dialogAviso.querySelectorAll('button')).find(b => {
            const t = (b.textContent || '').trim().toUpperCase();
            return t === 'OK' || t.includes('OK');
        });

        if (btnOk) {
            console.log('[CAF] (Etapa 4) Clicando no botão OK do diálogo de aviso...');
            btnOk.focus();
            btnOk.click();
            await sleep(300);
            await waitForLoader();
    if (cafAbort) return false;
            return true;
        }
    }
    return false;
}

async function inserirProdutoUnico(p, isAuto = false) {
    cafAbort = false;
    // ETAPAS 1 a 3: Clicar Rendas -> Clicar Ações -> Clicar Adicionar
    await acionarBotaoAdicionarRenda();

    // ETAPA 4: Verificar e clicar no OK da mensagem de documento comprobatório
    await fecharAvisoComprobatorioRenda();

    // Aguardar o modal/form de cadastro renderizar ativamente na tela
    let modalAberta = false;
    for (let i = 0; i < 25; i++) {
        await fecharAvisoComprobatorioRenda();

        const inputProduto = document.getElementById('idProduto');
        const inputEstimada = document.getElementById('rendaEstimada');
        const selectTipo = document.getElementById('mui-component-select-idTipoRenda');
        if (inputProduto || inputEstimada || selectTipo) {
            modalAberta = true;
            break;
        }
        await sleep(300);
    }

    if (!modalAberta) {
        showToast('Erro: Janela de Cadastro de Renda não abriu.', false);
        return false;
    }
    await waitForLoader();
    if (cafAbort) return false; // Garante que não há nenhum spinner bloqueando os cliques na janela recém-aberta
    await sleep(200);

    // ETAPA 5: SELECIONAR O PRODUTO PRIMEIRO (pois ele carrega os Tipos de Renda no backend)
    if (p.nomeOficial) {
        console.log(`[CAF] (Etapa 5) Preenchendo Produto em primeiro lugar: ${p.nomeOficial}`);

        let inputProduto = null;
        for (let i = 0; i < 50; i++) {
            inputProduto = document.getElementById('idProduto');
            if (inputProduto && !inputProduto.disabled) break;
            await sleep(200);
        }

        if (inputProduto && !inputProduto.disabled) {
            inputProduto.focus();
            await sleep(300);

            const normalizeText = (t) => t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, ' ').trim();
            const targetText = normalizeText(p.nomeOficial);

            let baseName = p.nomeOficial.split(' - ')[0].replace(/\(.*?\)/g, '').trim();
            let termoBusca = baseName.length > 25 ? baseName.substring(0, 25).trim() : baseName;

            inputProduto.value = '';
            document.execCommand('insertText', false, termoBusca);
            inputProduto.dispatchEvent(new Event('input', { bubbles: true }));

            // Monitoramento Ativo: Aguarda a lista de sugestões de produto abrir
            let resultadosCarregaram = false;
            for (let i = 0; i < 50; i++) {
                if (i % 3 === 0) {
                    inputProduto.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowDown', code: 'ArrowDown', keyCode: 40, bubbles: true }));
                }
                if (document.querySelector('[role="listbox"] li, .MuiAutocomplete-option')) {
                    resultadosCarregaram = true;
                    break;
                }
                await sleep(200);
            }

            if (resultadosCarregaram) {
                await sleep(300);
                const opcoes = Array.from(document.querySelectorAll('[role="listbox"] li, .MuiAutocomplete-option'));
                let optionFound = null;

                for (let li of opcoes) {
                    const liText = normalizeText(li.textContent || '');
                    if (liText === targetText || liText.includes(targetText) || targetText.includes(liText)) {
                        optionFound = li;
                        break;
                    }
                }

                if (optionFound) {
                    console.log(`[CAF] Produto selecionado na lista: ${optionFound.textContent}`);
                    optionFound.scrollIntoView({ block: 'nearest' });
                    optionFound.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
                    optionFound.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
                    optionFound.click();
                    await sleep(300);

                    inputProduto.focus();
                    inputProduto.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));
                    simularTecla('Tab', 9, inputProduto);
                    await sleep(300);
                } else {
                    console.warn(`[CAF] Produto não encontrado na lista de sugestões!`);
                    inputProduto.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));
                }
            } else {
                console.warn(`[CAF] O servidor não retornou a lista de produtos a tempo!`);
                inputProduto.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));
            }
        }
    }

    // Aguarda o backend do CAF carregar os tipos de renda correspondentes ao produto escolhido
    await waitForLoader();
    if (cafAbort) return false;
    await sleep(500);

    // ETAPA 6: SELECIONAR O TIPO DE RENDA (carregado a partir da etapa 5)
    if (p.tipoRenda) {
        console.log(`[CAF] (Etapa 6) Selecionando Tipo de Renda carregado: ${p.tipoRenda}`);

        const selectDiv = document.getElementById('mui-component-select-idTipoRenda');
        if (selectDiv) {
            selectDiv.focus();
            await sleep(200);

            selectDiv.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));

            let listaRenderizada = false;
            for (let i = 0; i < 50; i++) {
                if (document.querySelector('[role="listbox"] li, .MuiMenuItem-root')) {
                    listaRenderizada = true;
                    break;
                }
                await sleep(100);
            }

            if (listaRenderizada) {
                await sleep(200);

                const textoParaDigitar = p.tipoRenda.length > 25 ? p.tipoRenda.substring(0, 25) : p.tipoRenda;

                for (let char of textoParaDigitar) {
                    document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: char, bubbles: true }));
                    await sleep(15);
                }

                await sleep(300);
                document.activeElement.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true }));

                console.log(`[CAF] Tipo de renda '${p.tipoRenda}' selecionado!`);
            } else {
                console.warn(`[CAF] Lista do Tipo de Renda demorou demais para abrir!`);
            }
            await sleep(400);
        }
    }

    // ETAPA 7: Colar os valores auferidos/estimados, marcar "Não" em agroecológica e clicar em Salvar
    const valStr = p.valTotal.toLocaleString('pt-BR', { minimumFractionDigits: 2 });

    const inputEstimada = document.getElementById('rendaEstimada') || findMUIField('Renda estimada');
    if (inputEstimada) {
        inputEstimada.focus();
        setReactInputValue(inputEstimada, valStr);
    }

    const inputAuferida = document.getElementById('rendaAuferida') || findMUIField('Renda auferida');
    if (inputAuferida) {
        inputAuferida.focus();
        setReactInputValue(inputAuferida, valStr);
    }

    // Produção agroecológica ("Não")
    clickRadio('produção', 'não');
    const radioNao = document.querySelector('input[name="producaoAgroecologica"][value="0"]');
    if (radioNao) radioNao.click();

    // Clicar em Salvar
    if (!isAuto) {
        showToast('Produto preenchido! Verifique e clique em Salvar.', true);
        return true;
    } else {
        const btnSalvar = findButtonByText('Salvar') || findButtonByText('Confirmar');
        if (btnSalvar) {
            btnSalvar.click();
            await waitForLoader();
    if (cafAbort) return false;

            const normalizeText = (t) => t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/\s+/g, ' ').trim();
            const targetText = normalizeText(p.nomeOficial);

            let salvoComSucesso = false;
            for (let i = 0; i < 60; i++) { // Espera até 12 segundos pelo salvamento no servidor
                const celulasProduto = Array.from(document.querySelectorAll('table tbody tr td:nth-child(2)'));
                const itemNaTabela = celulasProduto.some(td => {
                    const txt = normalizeText(td.textContent || '');
                    return txt === targetText || txt.includes(targetText);
                });

                const modalFechado = document.getElementById('idProduto') === null;

                if (itemNaTabela && modalFechado) {
                    salvoComSucesso = true;
                    break;
                }
                await sleep(200);
            }

            if (salvoComSucesso) {
                console.log(`[CAF] Sucesso absoluto: Produto '${p.nomeOficial}' verificado na tabela principal!`);
                return true;
            } else {
                console.warn(`[CAF] Alerta: Produto '${p.nomeOficial}' demorou muito a salvar ou não apareceu na tabela.`);
                return false;
            }
        }
    }
    return false;
}

function isCPFRegistered(cpf) {
    if (!cpf) return false;
    const cleanCpf = cpf.replace(/\D/g, '');
    if (cleanCpf.length !== 11) return false;

    // Procurar em todas as tabelas na página (ignora as tabelas do próprio assistente)
    const tables = document.querySelectorAll('table');
    for (const table of tables) {
        if (table.closest('#caf-assist-panel') || table.closest('#caf-info-modal')) {
            continue;
        }
        const rows = table.querySelectorAll('tbody tr');
        for (const row of rows) {
            const cells = row.querySelectorAll('td');
            for (const cell of cells) {
                const text = cell.textContent || '';
                const cleanCellText = text.replace(/\D/g, '');
                if (cleanCellText.includes(cleanCpf)) {
                    return true;
                }
            }
        }
    }
    return false;
}




async function inserirMembroUnico(idx, isAuto = false) {
    cafAbort = false;
    if (!loadedData || !loadedData.membros || idx >= loadedData.membros.length) {
        showToast('Membro inválido!', false);
        return false;
    }

    const m = loadedData.membros[idx];
    selectedMembroIdx = idx;

    // Atualiza a seleção visual na lista e no seletor
    const membroSelect = document.getElementById('caf-membro-select');
    if (membroSelect) membroSelect.value = idx;
    document.querySelectorAll('.caf-membro-row').forEach((r, rIdx) => {
        r.style.background = rIdx === idx ? 'rgba(59, 130, 246, 0.15)' : 'transparent';
    });
    autoDetectTab();

    showToast(`Iniciando inserção de ${m.nome.split(' ')[0]}...`, true);

    // 1. Verificar se estamos na tela de consulta de CPF (cpfConsulta e dataNascimentoConsulta visíveis)
    let inputCPFConsulta = document.getElementById('cpfConsulta') || findCPFInput();

    if (!inputCPFConsulta) {
        // Se for um membro adicional (idx > 0), tentar garantir que estamos na aba de Composição Familiar / Membros
        if (idx > 0) {
            const tabs = Array.from(document.querySelectorAll('[role="tab"], .MuiTab-root, button.MuiTab-root'));
            const memberTab = tabs.find(t => {
                const txt = (t.textContent || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                return txt.includes('composicao familiar') || txt.includes('grupo familiar') || txt.includes('membros');
            });
            if (memberTab && !memberTab.classList.contains('Mui-selected') && memberTab.getAttribute('aria-selected') !== 'true') {
                console.log(`[CAF] Alternando para a aba de Composição Familiar...`);
                memberTab.click();
                await waitForLoader();
                if (cafAbort) return false;
                await sleep(500);
            }
        }

        // Tenta abrir o formulário pelo Popover Menu "Adicionar" do Grupo Familiar ou botão dedicado
        const abriu = await abrirFormularioMembro();
        if (abriu) {
            inputCPFConsulta = document.getElementById('cpfConsulta') || findCPFInput();
        }
    }

    if (!inputCPFConsulta) {
        showToast(`Abra o formulário de membros ou a aba Grupo Familiar para inserir ${m.nome.split(' ')[0]}.`, false);
        return false;
    }

    // 2. Chamar fillMembro() que realiza a consulta e aguarda a RF antes de preencher o restante dos campos
    await fillMembro();

    // 3. Clicar em Salvar / Confirmar (se automático)
    if (!isAuto) {
        showToast('Preenchimento concluído! Verifique e clique em Salvar.', true);
        return true;
    }

    const btnSalvar = findButtonByText('Salvar') || findButtonByText('Confirmar');
    if (btnSalvar) {
        console.log(`[CAF] Clicando no botão Salvar para o membro ${m.nome.split(' ')[0]}...`);
        btnSalvar.click();

        // Espera o spinner de carregamento sumir
        await waitForLoader();
    if (cafAbort) return false;

        // Monitora se o modal de cadastro de membro fechou (sinal de sucesso)
        let salvoComSucesso = false;
        for (let j = 0; j < 40; j++) { // Espera até 8 segundos
            const cpfInputFechado = document.getElementById('cpfConsulta') === null;
            if (cpfInputFechado) {
                salvoComSucesso = true;
                break;
            }
            await sleep(200);
        }

        if (salvoComSucesso) {
            showToast(`Membro ${m.nome.split(' ')[0]} cadastrado com sucesso!`, true);
            return true;
        } else {
            console.warn(`[CAF] Alerta: O formulário de membro não parece ter fechado após clicar em Salvar.`);
            return false;
        }
    } else {
        showToast(`Botão Salvar não localizado para o membro ${m.nome.split(' ')[0]}!`, false);
        return false;
    }
}

async function adicionarTodosMembros() {
    if (!loadedData || !loadedData.membros || loadedData.membros.length === 0) {
        showToast('Nenhum membro carregado para adicionar!', false);
        return;
    }

    const confirmacao = confirm(`Deseja adicionar em lote todos os membros não cadastrados automaticamente?`);
    if (!confirmacao) return;

    showToast('Iniciando preenchimento em lote de membros...', true);

    for (let i = 0; i < loadedData.membros.length; i++) {
        const m = loadedData.membros[i];

        // Verificar se já está cadastrado na tela do Serpro
        if (isCPFRegistered(m.cpf)) {
            showToast(`Membro ${m.nome.split(' ')[0]} já está cadastrado. Pulando...`, true);
            await sleep(200);
            continue;
        }

        const sucesso = await inserirMembroUnico(i, true);
        if (sucesso) {
            await sleep(500);
        } else {
            showToast(`Atenção: O cadastro de ${m.nome.split(' ')[0]} falhou.`, false);
            const continuar = confirm(`O preenchimento de ${m.nome.split(' ')[0]} não foi concluído. Deseja continuar com os próximos membros?`);
            if (!continuar) {
                showToast('Processamento em lote interrompido pelo usuário.', false);
                return;
            }
            await sleep(500);
        }
    }

    showToast('Processamento em lote de membros finalizado!', true);
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// Inicializar assistente
setTimeout(createUI, 1000);

// =========================================================================
// 8. AUTOMAÇÃO DE ANEXO DE PDFs EM LOTE NA ABA RENDA
// =========================================================================

let uploadedBatchPDFs = [];

function carregarPDFsDoJSON(dados) {
    if (dados && dados.notasPDFs && Array.isArray(dados.notasPDFs) && dados.notasPDFs.length > 0) {
        let carregados = 0;
        dados.notasPDFs.forEach(item => {
            if (item.name && item.base64) {
                if (!uploadedBatchPDFs.some(f => f.name === item.name)) {
                    try {
                        const binStr = atob(item.base64);
                        const len = binStr.length;
                        const bytes = new Uint8Array(len);
                        for (let i = 0; i < len; i++) bytes[i] = binStr.charCodeAt(i);
                        const blob = new Blob([bytes], { type: 'application/pdf' });
                        const file = new File([blob], item.name, { type: 'application/pdf' });
                        uploadedBatchPDFs.push(file);
                        carregados++;
                    } catch (e) {
                        console.error('[CAF] Erro ao decodificar PDF do JSON:', item.name, e);
                    }
                }
            }
        });
        if (carregados > 0) {
            updateBatchPDFsUI();
            console.log(`[CAF] ${carregados} PDF(s) do JSON carregados automaticamente para anexo em lote.`);
        }
    }
}

function handleBatchPDFs(files) {
    if (!files || files.length === 0) return;
    let countNovos = 0;
    for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.name.toLowerCase().endsWith('.pdf') || file.type === 'application/pdf') {
            if (!uploadedBatchPDFs.some(f => f.name === file.name && f.size === file.size)) {
                uploadedBatchPDFs.push(file);
                countNovos++;
            }
        }
    }
    updateBatchPDFsUI();
    if (countNovos > 0) {
        showToast(`${countNovos} PDF(s) carregado(s) com sucesso! Total: ${uploadedBatchPDFs.length}`, true);
    }
}

function updateBatchPDFsUI() {
    const badge = document.getElementById('caf-pdf-count-badge');
    const list = document.getElementById('caf-pdf-names-list');
    if (badge) {
        badge.textContent = `${uploadedBatchPDFs.length} PDF${uploadedBatchPDFs.length === 1 ? '' : 's'}`;
    }
    if (list) {
        if (uploadedBatchPDFs.length > 0) {
            list.style.display = 'block';
            list.innerHTML = uploadedBatchPDFs.map((f, idx) => `
                <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:2px; border-bottom:1px solid rgba(255,255,255,0.05); padding-bottom:2px;">
                    <span style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:180px;" title="${f.name}">📄 ${f.name}</span>
                    <span style="color:#ef4444; cursor:pointer; font-weight:bold; margin-left:4px; padding:0 3px;" class="caf-remove-pdf-btn" data-idx="${idx}" title="Remover este arquivo">✕</span>
                </div>
            `).join('');

            list.querySelectorAll('.caf-remove-pdf-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    const idx = parseInt(e.target.getAttribute('data-idx'));
                    uploadedBatchPDFs.splice(idx, 1);
                    updateBatchPDFsUI();
                });
            });
        } else {
            list.style.display = 'none';
            list.innerHTML = '';
        }
    }
}

async function acionarModalAnexarDocumentosRenda() {
    // 1. Verificar se o modal de Anexar Documentos já está aberto
    const modalAberto = Array.from(document.querySelectorAll('[role="dialog"], .MuiDialog-paper')).find(d => {
        const txt = (d.textContent || '').toLowerCase();
        return txt.includes('anexar documentos') || txt.includes('documentos comprobatórios') || (txt.includes('anexar') && txt.includes('documento'));
    });
    if (modalAberto) return modalAberto;

    // 2. Tentar encontrar botão direto "Anexar Documentos"
    const allBtns = Array.from(document.querySelectorAll('button, .MuiButton-root, [role="button"]'))
        .filter(b => !b.closest('#caf-assist-panel') && !b.closest('#caf-info-modal'));

    let btnAnexar = allBtns.find(b => {
        const txt = (b.textContent || '').trim().toLowerCase();
        return txt === 'anexar documentos' || txt.includes('anexar documentos');
    });

    if (btnAnexar) {
        console.log('[CAF] Clicando no botão direto "Anexar Documentos"...', btnAnexar);
        btnAnexar.focus();
        btnAnexar.click();
    } else {
        // 3. Abrir via menu "Ações"
        console.log('[CAF] Abrindo menu Ações para localizar "Anexar Documentos"...');
        const accordionSummaries = Array.from(document.querySelectorAll('.MuiAccordionSummary-root, .MuiAccordionSummary-content'));
        const accordionRendas = accordionSummaries.find(el => {
            const txt = (el.textContent || '').toLowerCase();
            return txt.includes('rendas do estabelecimento') && !txt.includes('fora do estabelecimento');
        });
        if (accordionRendas) {
            const parentAccordion = accordionRendas.closest('.MuiAccordion-root');
            if (parentAccordion && !parentAccordion.classList.contains('Mui-expanded') && accordionRendas.getAttribute('aria-expanded') !== 'true') {
                accordionRendas.click();
                await sleep(300);
            }
        }

        let btnAcoes = allBtns.find(b => {
            const txt = (b.textContent || '').trim().toLowerCase();
            const grandParentTxt = (b.closest('.MuiPaper-root, .MuiAccordion-root, section') ? b.closest('.MuiPaper-root, .MuiAccordion-root, section').textContent || '' : '').toLowerCase();
            const isAcoes = txt === 'ações' || txt === 'acoes' || txt.includes('ações');
            const isNoContainerRendas = grandParentTxt.includes('rendas do estabelecimento') && !grandParentTxt.includes('fora do estabelecimento');
            return isAcoes && (isNoContainerRendas || b.getAttribute('aria-haspopup') === 'true');
        });

        if (btnAcoes) {
            btnAcoes.focus();
            btnAcoes.click();
            await sleep(300);
        }

        // Aguardar o item "Anexar Documentos" aparecer no menu popover
        let itemAnexar = null;
        for (let i = 0; i < 20; i++) {
            const items = Array.from(document.querySelectorAll('[role="menuitem"], .MuiMenuItem-root, li.MuiMenuItem-root, .MuiPopover-paper li, .MuiMenu-paper li'));
            itemAnexar = items.find(it => {
                const txt = (it.textContent || '').trim().toLowerCase();
                return txt.includes('anexar') || txt.includes('documento');
            });
            if (itemAnexar) break;
            await sleep(150);
        }

        if (itemAnexar) {
            console.log('[CAF] Clicando no item "Anexar Documentos" do menu...', itemAnexar);
            itemAnexar.click();
        } else {
            console.warn('[CAF] Não foi possível localizar a opção "Anexar Documentos".');
            return null;
        }
    }

    await waitForLoader();
    await sleep(400);

    // Aguarda o modal de diálogo aparecer
    for (let i = 0; i < 25; i++) {
        const dialog = Array.from(document.querySelectorAll('[role="dialog"], .MuiDialog-paper')).find(d => {
            const txt = (d.textContent || '').toLowerCase();
            return txt.includes('anexar') || txt.includes('documento') || d.querySelector('input[type="file"]');
        });
        if (dialog) return dialog;
        await sleep(200);
    }
    return null;
}

async function anexarDocumentosEmLoteNoCAF() {
    cafAbort = false;
    if (!uploadedBatchPDFs || uploadedBatchPDFs.length === 0) {
        showToast('Nenhum PDF carregado! Clique em "📥 Carregar PDFs" primeiro.', false);
        return;
    }

    showToast(`Iniciando anexo de ${uploadedBatchPDFs.length} PDF(s)...`, true);

    const dialog = await acionarModalAnexarDocumentosRenda();
    if (!dialog) {
        showToast('Erro: Janela de Anexo de Documentos não abriu no CAF.', false);
        return;
    }

    let sucessos = 0;
    for (let i = 0; i < uploadedBatchPDFs.length; i++) {
        if (cafAbort) {
            showToast('Processo cancelado pelo usuário.', false);
            break;
        }

        const file = uploadedBatchPDFs[i];
        showToast(`Anexando (${i + 1}/${uploadedBatchPDFs.length}): ${file.name}...`, true);

        // 1. Localizar o input de arquivo no diálogo
        let fileInput = dialog.querySelector('input[type="file"]') || document.querySelector('input[type="file"]:not(#caf-file-input):not(#caf-upload-batch-pdfs)');
        
        // Se o input não estiver disponível de imediato, tenta clicar no botão "Adicionar" dentro do modal
        if (!fileInput) {
            const btnAdicionar = Array.from(dialog.querySelectorAll('button, .MuiButton-root')).find(b => {
                const txt = (b.textContent || '').trim().toLowerCase();
                return txt.includes('adicionar') || txt.includes('anexar') || txt.includes('novo');
            });
            if (btnAdicionar) {
                btnAdicionar.click();
                await sleep(300);
                fileInput = dialog.querySelector('input[type="file"]') || document.querySelector('input[type="file"]:not(#caf-file-input):not(#caf-upload-batch-pdfs)');
            }
        }

        if (!fileInput) {
            showToast(`Erro: Campo de upload não localizado para ${file.name}.`, false);
            console.error('[CAF] Input file não localizado no diálogo:', dialog);
            continue;
        }

        try {
            const dt = new DataTransfer();
            dt.items.add(file);
            fileInput.files = dt.files;
            fileInput.dispatchEvent(new Event('change', { bubbles: true }));
            fileInput.dispatchEvent(new Event('input', { bubbles: true }));

            // Aguardar o envio e processamento pelo backend do CAF
            await waitForLoader();
            await sleep(800);
            sucessos++;
            console.log(`[CAF] Arquivo '${file.name}' anexado com sucesso!`);
        } catch (err) {
            console.error(`[CAF] Falha ao anexar ${file.name}:`, err);
            showToast(`Falha ao anexar ${file.name}: ${err.message}`, false);
        }
    }

    if (sucessos > 0) {
        showToast(`🎉 Sucesso! ${sucessos} de ${uploadedBatchPDFs.length} PDF(s) foram anexados no CAF!`, true);
    }
}

// Listener de mensagens para o proxy do caf-coleta.html (Bypass de CORS para PDFs)
window.addEventListener('message', async (event) => {
    if (!event.data || !event.data.type) return;

    if (event.data.type === 'PING_TAMPERMONKEY') {
        event.source.postMessage({ type: 'PONG_TAMPERMONKEY' }, '*');
    } else if (event.data.type === 'FETCH_SEFAZ_PDF') {
        const { url, requestId, chave } = event.data;
        console.log('[Assistente] Recebeu solicitação para buscar PDF da chave:', chave);

        if (typeof GM_xmlhttpRequest === 'undefined') {
            event.source.postMessage({
                type: 'FETCH_SEFAZ_PDF_ERROR',
                requestId: requestId,
                chave: chave,
                error: 'GM_xmlhttpRequest não está disponível no Tampermonkey.'
            }, '*');
            return;
        }

        GM_xmlhttpRequest({
            method: 'GET',
            url: url,
            responseType: 'arraybuffer',
            onload: function (response) {
                if (response.status === 200) {
                    const arrayBuffer = response.response;
                    // Converter ArrayBuffer para base64
                    let binary = '';
                    const bytes = new Uint8Array(arrayBuffer);
                    const len = bytes.byteLength;
                    for (let i = 0; i < len; i++) {
                        binary += String.fromCharCode(bytes[i]);
                    }
                    const base64 = window.btoa(binary);

                    event.source.postMessage({
                        type: 'FETCH_SEFAZ_PDF_SUCCESS',
                        requestId: requestId,
                        chave: chave,
                        base64: base64
                    }, '*');
                } else {
                    event.source.postMessage({
                        type: 'FETCH_SEFAZ_PDF_ERROR',
                        requestId: requestId,
                        chave: chave,
                        error: 'Status HTTP ' + response.status
                    }, '*');
                }
            },
            onerror: function (error) {
                event.source.postMessage({
                    type: 'FETCH_SEFAZ_PDF_ERROR',
                    requestId: requestId,
                    chave: chave,
                    error: 'Erro de rede ou bloqueio ao acessar portal.'
                }, '*');
            }
        });
    }
});

